import assert from 'node:assert/strict';import {createRequire} from 'node:module';import {writeFileSync,readFileSync} from 'node:fs';import {resolve,join} from 'node:path';import {createHash} from 'node:crypto';
const root=resolve(process.env.HE_SOURCE_ROOT),require=createRequire(join(root,'package.json')),sharp=require('sharp');assert.equal(process.version,'v24.22.1');const hash=b=>createHash('sha256').update(b).digest('hex');
const cases=[];async function add(name,input,page=0){const m=await sharp(input,{limitInputPixels:20000000,failOn:'warning'}).metadata();const png=await sharp(input,{page,pages:1,limitInputPixels:20000000,failOn:'warning'}).resize({width:512,height:512,fit:'inside',withoutEnlargement:true}).png().toBuffer();const webp=await sharp(input,{page:0,pages:1,limitInputPixels:20000000}).rotate().resize(320,320,{fit:'inside',withoutEnlargement:true}).webp({quality:75}).toBuffer();cases.push({name,input:input.toString('base64'),width:m.width,height:m.pageHeight??m.height,frames:m.pages??1,page,png:hash(png),webp:hash(webp)})}
function rgba(w,h){const b=Buffer.alloc(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let i=(y*w+x)*4;b[i]=(x*13+y*7)%256;b[i+1]=(x*5+y*11)%256;b[i+2]=(x*17+y*3)%256;b[i+3]=(x+y)%5?255:90}return b}
const raw=rgba(43,29);for(const format of ['png','jpeg','webp'])await add(format,await sharp(raw,{raw:{width:43,height:29,channels:4}})[format]().toBuffer());
for(let orientation=1;orientation<=8;orientation++)await add(`orientation-${orientation}`,await sharp(raw,{raw:{width:43,height:29,channels:4}}).withMetadata({orientation}).jpeg().toBuffer());
for(const [width,height]of [[1025,77],[77,1025],[641,479],[1,800]])await add(`resize-${width}-${height}`,await sharp(rgba(width,height),{raw:{width,height,channels:4}}).png().toBuffer());
const animated=rgba(17,18);for(const format of ['gif','webp']){const input=await sharp(animated,{raw:{width:17,height:18,channels:4,pageHeight:6}})[format]({delay:[50,70,90],loop:0}).toBuffer();for(const page of [0,1,2])await add(`animated-${format}-${page}`,input,page)}
writeFileSync(new URL('meme-sharp.json',import.meta.url),JSON.stringify({node:process.version,sharp:sharp.versions,sourceHash:hash(readFileSync(join(root,'src/memes.ts'))),cases},null,2)+'\n');console.log(`${cases.length} exact metadata/frame/thumbnail Sharp cases`);
